from openpyxl import load_workbook
wb=load_workbook('/root/output/result.xlsx', data_only=False)
ws=wb['Task']
# Ensure all cells in blocks have formulas
blocks=[('H12','L17'),('H19','L24'),('H26','L31')]

def addr_to_rc(addr):
    import re
    m=re.match(r'([A-Z]+)(\d+)',addr)
    col=m.group(1); row=int(m.group(2))
    return col,row

def col_to_num(c):
    n=0
    for ch in c:
        n=n*26+(ord(ch)-64)
    return n

def num_to_col(n):
    s=''
    while n:
        n, r = divmod(n-1,26)
        s=chr(65+r)+s
    return s

issues=[]
